UES(?,?,?,NOW())');foreach($sel as $cid)if(sk1380_category($cid))$ins->execute([sk1380_tid(),$p['id'],$cid]);$pdo->commit();$msg=$p['status']==='approved'?'Profile updated.':'Application submitted for admin approval.';$existing=sk1380_provider();}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}sk1380_shell('Become a Service Provider','provider-apply');?><section class="form-hero"><span class="eyebrow">SERVICE PROVIDER ACCOUNT</span><h1>Apni service business ko ShahkotPK par laayein.</h1><p>Har provider ka separate approved profile aur dashboard hota hai. Approval ke baad quotes, bookings, packages aur Fast Service tools unlock hote hain.</p></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><?php if($existing):?><div class="status-card"><b>Application status: <?=sk1380_h(strtoupper($existing['status']))?></b><span>Verification: <?=sk1380_h($existing['verification_status'])?></span><?php if($existing['status']==='approved'):?><a href="/provider/services.php">Open Provider Dashboard →</a><?php endif;?></div><?php endif;?><form method="post" class="pro-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><div class="two"><label>Your / technician display name<input name="display_name" required value="<?=sk1380_h($existing['display_name']??sk1380_user_label(sk1380_uid()))?>"></label><label>Business / shop name (optional)<input name="business_name" value="<?=sk1380_h($existing['business_name']??'')?>"></label></div><label>About your skills & experience<textarea name="bio" rows="5"><?=sk1380_h($existing['bio']??'')?></textarea></label><div class="three"><label>Service area<input name="area" required value="<?=sk1380_h($existing['area']??'Shahkot')?>"></label><label>Public contact (optional)<input name="phone_public" value="<?=sk1380_h($existing['phone_public']??'')?>"></label><label>Years experience<input type="number" min="0" max="80" name="years_experience" value="<?=sk1380_h($existing['years_experience']??0)?>"></label></div><label>Service radius (km)<input type="number" min="1" max="100" name="radius" value="<?=sk1380_h($existing['service_radius_km']??10)?>"></label><fieldset><legend>Services you provide</legend><div class="check-grid"><?php $current=$existing?array_column(sk1380_provider_categories((int)$existing['id']),'id'):[];foreach($cats as $c):?><label><input type="checkbox" name="categories[]" value="<?=$c['id']?>" <?=in_array($c['id'],$current)?'checked':''?>> <span><?=sk1380_h($c['icon'])?></span><?=sk1380_h($c['name'])?></label><?php endforeach;?></div></fieldset><button class="btn">Submit / Update Application</button></form><?php sk1380_end();